/**
 * The runtime-loaded font cuts. Each key becomes the `fontFamily` the app can reference
 * (expo-font registers the asset under its key), so keys MUST equal the file basenames —
 * font-contract.test.ts enforces the sync, plus glyph coverage and figure features.
 *
 * Files are generated by `scripts/build-fonts.py` (pinned google/fonts sources, subset to
 * the app's repertoire) and committed. Inter (opsz 14) is the app voice — product-grade UI
 * sans in the Linear/Notion register, chosen 2026-07-18 after the Cormorant serif takeover
 * was rejected on-device as unreadable; swapping faces again = regenerate cuts, update
 * these entries and the `Face` map.
 */
export const FontAssets = {
  'Inter-Regular': require('../../assets/fonts/Inter-Regular.ttf'),
  'Inter-SemiBold': require('../../assets/fonts/Inter-SemiBold.ttf'),
  'Inter-Bold': require('../../assets/fonts/Inter-Bold.ttf'),
} as const;
